macro_rules! deps {
    () => {
        Database!();
    };
}

macro_rules! memory_usage {
    () => {
        deps!();
        # [cfg (feature = "salsa_unstable")] mod memory_usage { use hashbrown :: HashMap ; use crate :: Database ; impl dyn Database { # [doc = " Returns memory usage information about ingredients in the database."] pub fn memory_usage (& self) -> DatabaseInfo { let mut queries = HashMap :: new () ; let mut structs = Vec :: new () ; for input_ingredient in self . zalsa () . ingredients () { let Some (input_info) = input_ingredient . memory_usage (self) else { continue ; } ; let mut size_of_fields = 0 ; let mut size_of_metadata = 0 ; let mut count = 0 ; let mut heap_size_of_fields = None ; for input_slot in input_info { count += 1 ; size_of_fields += input_slot . size_of_fields ; size_of_metadata += input_slot . size_of_metadata ; if let Some (slot_heap_size) = input_slot . heap_size_of_fields { heap_size_of_fields = Some (heap_size_of_fields . unwrap_or_default () + slot_heap_size) ; } for memo in input_slot . memos { let info = queries . entry (memo . debug_name) . or_insert (IngredientInfo { debug_name : memo . output . debug_name , .. Default :: default () }) ; info . count += 1 ; info . size_of_fields += memo . output . size_of_fields ; info . size_of_metadata += memo . output . size_of_metadata ; if let Some (memo_heap_size) = memo . output . heap_size_of_fields { info . heap_size_of_fields = Some (info . heap_size_of_fields . unwrap_or_default () + memo_heap_size) ; } } } structs . push (IngredientInfo { count , size_of_fields , size_of_metadata , heap_size_of_fields , debug_name : input_ingredient . debug_name () , }) ; } DatabaseInfo { structs , queries } } } # [doc = " Memory usage information about ingredients in the Salsa database."] pub struct DatabaseInfo { # [doc = " Information about any Salsa structs."] pub structs : Vec < IngredientInfo > , # [doc = " Memory usage information for memoized values of a given query, keyed"] # [doc = " by the query function name."] pub queries : HashMap < & 'static str , IngredientInfo > , } # [doc = " Information about instances of a particular Salsa ingredient."] # [derive (Default , Debug , PartialEq , Eq , PartialOrd , Ord)] pub struct IngredientInfo { debug_name : & 'static str , count : usize , size_of_metadata : usize , size_of_fields : usize , heap_size_of_fields : Option < usize > , } impl IngredientInfo { # [doc = " Returns the debug name of the ingredient."] pub fn debug_name (& self) -> & 'static str { self . debug_name } # [doc = " Returns the total stack size of the fields of any instances of this ingredient, in bytes."] pub fn size_of_fields (& self) -> usize { self . size_of_fields } # [doc = " Returns the total heap size of the fields of any instances of this ingredient, in bytes."] # [doc = ""] # [doc = " Returns `None` if the ingredient doesn't specify a `heap_size` function."] pub fn heap_size_of_fields (& self) -> Option < usize > { self . heap_size_of_fields } # [doc = " Returns the total size of Salsa metadata of any instances of this ingredient, in bytes."] pub fn size_of_metadata (& self) -> usize { self . size_of_metadata } # [doc = " Returns the number of instances of this ingredient."] pub fn count (& self) -> usize { self . count } } # [doc = " Memory usage information about a particular instance of struct, input or output."] pub struct SlotInfo { pub (crate) debug_name : & 'static str , pub (crate) size_of_metadata : usize , pub (crate) size_of_fields : usize , pub (crate) heap_size_of_fields : Option < usize > , pub (crate) memos : Vec < MemoInfo > , } # [doc = " Memory usage information about a particular memo."] pub struct MemoInfo { pub (crate) debug_name : & 'static str , pub (crate) output : SlotInfo , } }
    };
}

memory_usage!();